<?php
require __DIR__ . '/includes/auth.php'; require_login(); require __DIR__ . '/config/database.php'; require __DIR__ . '/config/collection_schedule.php';
$is_staff = ($_SESSION['user_role'] ?? '') === 'staff';
if ($is_staff) {
    $notes = $pdo->prepare('SELECT title,message,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 3');
    $notes->execute([$_SESSION['user_id']]); $notes = $notes->fetchAll();
    $count = $pdo->prepare('SELECT COUNT(*) FROM stationery_requests WHERE requester_id=? AND status="pending"'); $count->execute([$_SESSION['user_id']]); $pending = (int)$count->fetchColumn();
} else {
    $total=(int)$pdo->query('SELECT COUNT(*) FROM items')->fetchColumn(); $out=(int)$pdo->query('SELECT COUNT(*) FROM items WHERE quantity<=0')->fetchColumn(); $pending=(int)$pdo->query('SELECT COUNT(*) FROM stationery_requests WHERE status="pending"')->fetchColumn();
}
?>
