ionery.php">✉ Request stationery</a><?php else:?><a class="active" href="dashboard.php">▦ Dashboard</a><a href="inventory.php">▤ Inventory</a><a href="stock_movement.php">↕ Stock movement</a><a href="admin_requests.php">✉ Staff requests</a><a href="manage_users.php">♙ Users</a><a href="reports.php">▥ Reports</a><a href="profile.php">♙ Profile</a><?php endif;?></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow"><?=$is_staff?'STAFF PORTAL':'ADMIN OVERVIEW'?></p><h1>Good morning, <?=htmlspecialchars($_SESSION['user_name'])?>!</h1></div><?php if($is_staff):?><a class="primary-btn" style="width:auto" href="request_stationery.php">+ New request</a><?php else:?><a class="primary-btn" style="width:auto" href="item_form.php">+ Add item</a><?php endif;?></header><?php if($is_staff):?><section class="staff-banner"><div><p>YOUR STAFF WORKSPACE</p><h2>Request the stationery you need</h2><span>Once approved, collect it at the ICT Counter on the fixed collection day.</span></div><span class="staff-mark">STAFF</span></section><section class="staff-actions"><a href="request_stationery.php"><span>✉</span><strong>Request Stationery</strong><small>Submit a new stationery request</small></a><a href="request_stationery.php"><span>🔔</span><strong><?=$pending?> Pending Request<?=$pending===1?'':'s'?></strong><small>Check your request status and notifications</small></a></section><section class="content-card"><h2>Collection Information</h2><div class="collection-card"><strong>Approved stationery collection</strong><br>Collect your approved request at the <strong><?=COLLECTION_LOCATION?></strong> on <strong><?=COLLECTION_DAY?></strong>, <?=COLLECTION_TIME?>.</div><h2 style="margin-top:24px">Latest Notifications</h2><?php if(!$notes):?><p class="muted">No notifications yet. Your collection details will appear here after a request is approved.</p><?php else:?><?php foreach($notes as $note):?><div class="notice"><strong><?=htmlspecialchars($note['title'])?></strong><span><?=htmlspecialchars($note['message'])?></span><br><small><?=date('d M Y, h:i A',strtotime($note['created_at']))?></small></div><?php endforeach;?><?php endif;?></section><?php else:?><section class="admin-cards"><article><span>📦</span><p>Total items</p><strong><?=$total?></strong></article><article><span>⚠️</span><p>Out of stock items</p><strong><?=$out?></strong></article><article><span>✉</span><p>Pending staff requests</p><strong><?=$pending?></strong></article></section><section class="content-card"><div class="section-heading"><div><h2>Admin quick actions</h2><p class="muted">Manage inventory, users, and Staff requests from the menu.</p></div><a href="admin_requests.php">View Staff requests →</a></div></section><?php endif;?></main></body></html>
